makeNtAlu(document.getElementById("alu-l4"),{"id": "l4", "ops": ["RLC", "RRC", "RL", "RR", "SWAP", "SHL", "SHR", "SAR", "DA", "ANL", "ORL"], "op": "RLC", "a": 21, "b": 48, "show": ["bcd", "asc"], "presets": [{"t": "×2: RLC 15H", "op": "RLC", "a": 21}, {"t": "÷2: RRC 2DH", "op": "RRC", "a": 45}, {"t": "Đèn chạy: RL 0FEH", "op": "RL", "a": 254}, {"t": "SWAP 47H", "op": "SWAP", "a": 71}, {"t": "BCD: 38H + 29H", "op": "DA", "a": 56, "b": 41}, {"t": "5 → ‘5’: ORL #30H", "op": "ORL", "a": 5, "b": 48}, {"t": "‘5’ → 5: ANL #0FH", "op": "ANL", "a": 53, "b": 15}, {"t": "−8 SAR", "op": "SAR", "a": 248}]});
makeMtLab(document.getElementById("lab-l4"),{id:"l4",scenarios:[{"label": "Ví dụ: Dịch trái = nhân 2 (CLR C, RLC A)", "note": "Bit 7 đi ra CY, 0 đi vào bit 0.", "steps": [{"t": "A = 15H = 21, CY = 0 (sau CLR C)", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">CLR C → 0C3H · 1 byte, 1 chu kỳ máy<\/p>", "say": "<p>Dịch trái 1 bit: mọi bit sang trái một cột, trọng số mỗi bit tăng gấp đôi, bit 0 nhận số 0. 8051 không có lệnh dịch riêng: dùng <code>CLR C<\/code> rồi <code>RLC A<\/code> (quay trái qua CY).<\/p>"}, {"t": "RLC A → 2AH = 42", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau RLC A<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">RLC A → 33H · 1 byte, 1 chu kỳ máy<\/p>", "ask": {"q": "Sau RLC A, cờ CY bằng bao nhiêu?", "o": ["1: phép dịch luôn đặt CY", "0: bit 7 cũ của 15H là 0"], "a": 1}, "say": "<p>CY (cột trái) đi vào bit 0, bit 7 cũ đi ra CY. Với CY = 0 trước lệnh, kết quả đúng bằng A × 2.<\/p>"}, {"t": "CLR C, RLC A lần nữa → 54H = 84", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>Sau RLC A<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div>", "ask": {"q": "A = 2AH = 42. Dịch trái thêm 1 bit được bao nhiêu?", "o": ["54H = 84", "2AH = 42", "0A8H = 168"], "a": 0}}, {"t": "Khi bit 7 = 1: bit thứ 9 ra CY", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Sau RLC A<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">90H × 2 = 144 × 2 = 288 = 1 0010 0000B: byte giữ 20H, CY = 1<\/p>", "say": "<p>Kết quả 9 bit nằm ở CY và A, giống số nhớ của phép cộng ở Bài 2. Muốn nhân 2 số lớn hơn 7FH phải xét CY hoặc dùng 16 bit.<\/p>"}]}, {"label": "Ví dụ: Dịch phải = chia 2, CY là số dư", "note": "45 ÷ 2 = 22 dư 1.", "steps": [{"t": "A = 2DH = 45, CY = 0", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div>", "say": "<p>Dịch phải logic 1 bit: mọi bit sang phải một cột, bit 7 nhận 0, bit 0 rơi ra ngoài. Trên 8051: <code>CLR C<\/code> rồi <code>RRC A<\/code>.<\/p>"}, {"t": "RRC A → 16H = 22, CY = 1", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau RRC A<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">RRC A → 13H · 1 byte, 1 chu kỳ máy<\/p>", "ask": {"q": "Bit 0 của 2DH bằng 1 rơi ra CY. CY = 1 cho biết gì về 45 ÷ 2?", "o": ["Phép chia bị tràn", "Số dư bằng 1: 45 = 2 × 22 + 1", "Thương lớn hơn 255"], "a": 1}}, {"t": "Quy tắc: dịch phải n bit = chia 2ⁿ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Phép<\/th><th scope=\"col\">Số không dấu<\/th><th scope=\"col\">Bit ra ngoài<\/th><\/tr><\/thead><tbody><tr><td>Dịch trái 1 bit<\/td><td>× 2 (mất bit 7)<\/td><td>bit 7 → CY<\/td><\/tr><tr><td>Dịch phải 1 bit<\/td><td>÷ 2, lấy phần nguyên<\/td><td>bit 0 → CY = số dư<\/td><\/tr><tr><td>Dịch phải 4 bit<\/td><td>÷ 16<\/td><td>4 bit thấp mất<\/td><\/tr><\/tbody><\/table>", "say": "<p>Quy tắc này chỉ đúng với số không dấu và khi bit đưa vào là 0. Số có dấu cần dịch phải số học (Ví dụ 8).<\/p>"}]}, {"label": "Ví dụ: Đèn chạy bằng RL A trên P\u0031", "note": "Quay không làm mất bit: số 0 chạy vòng.", "steps": [{"t": "A = 0FEH, MOV P\u0031,A: LED ở P\u0031.0 sáng", "html": "<div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 tắt, P\u0031.5 tắt, P\u0031.4 tắt, P\u0031.3 tắt, P\u0031.2 tắt, P\u0031.1 tắt, P\u0031.0 sáng\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>0 (thấp)<\/span><\/div><\/div><p class=\"mt-calc\">MOV P\u0031,A → 0F5H 90H · 2 byte, 1 chu kỳ máy<\/p>", "say": "<p>Giả định như Bài 1: LED sáng khi chân ở mức 0. Chỉ bit 0 bằng 0.<\/p>"}, {"t": "RL A → 0FDH, ghi P\u0031: LED ở P\u0031.1 sáng", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>Sau RL A<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 tắt, P\u0031.5 tắt, P\u0031.4 tắt, P\u0031.3 tắt, P\u0031.2 tắt, P\u0031.1 sáng, P\u0031.0 tắt\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>1 (cao)<\/span><\/div><\/div><p class=\"mt-calc\">RL A → 23H · 1 byte, 1 chu kỳ máy<\/p>", "ask": {"q": "Sau RL A và MOV P\u0031,A, LED nào sáng?", "o": ["LED ở P\u0031.0 và P\u0031.1", "LED ở P\u0031.7", "LED ở P\u0031.1"], "a": 2}, "say": "<p>Quay trái <code>RL A<\/code> không dùng CY: bit 7 quay về bit 0. Số 0 duy nhất đi lên một cột.<\/p>"}, {"t": "RL A → 0FBH: LED ở P\u0031.2 sáng", "html": "<div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 tắt, P\u0031.5 tắt, P\u0031.4 tắt, P\u0031.3 tắt, P\u0031.2 sáng, P\u0031.1 tắt, P\u0031.0 tắt\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>1 (cao)<\/span><\/div><\/div>"}, {"t": "Từ 7FH (LED 7), RL A → 0FEH", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Sau RL A<\/td><td class=\"new\">1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 tắt, P\u0031.5 tắt, P\u0031.4 tắt, P\u0031.3 tắt, P\u0031.2 tắt, P\u0031.1 tắt, P\u0031.0 sáng\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>0 (thấp)<\/span><\/div><\/div>", "ask": {"q": "A = 7FH (chỉ LED 7 sáng). RL A cho bao nhiêu?", "o": ["0FEH: quay vòng về LED 0", "0FFH: mọi LED tắt", "0FEH với CY = 0, LED 7 vẫn sáng"], "a": 0}, "say": "<p>Vì là phép quay nên số 0 không bị mất: đèn chạy vòng tròn mãi. Phép dịch (RLC với CY = 1) sẽ làm mất nó.<\/p>"}, {"t": "RR A: quay phải, chạy ngược chiều", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>Sau RR A<\/td><td class=\"new\">0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">RR A → 03H · 1 byte, 1 chu kỳ máy<\/p>", "say": "<p>Khi chạy thật cần một đoạn trễ giữa hai lần ghi P\u0031 (Chương 2 và khóa 8051); thiếu trễ, mắt chỉ thấy mọi LED sáng mờ.<\/p>"}]}, {"label": "Ví dụ: Tách BCD 47H ra hai ký tự ‘4’, ‘7’", "note": "SWAP, ANL #0FH, rồi cộng 30H.", "steps": [{"t": "BCD nén 47H: mỗi nibble một chữ số", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>47H<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">nibble cao 0100B = 4 · nibble thấp 0111B = 7 → số 47<\/p>", "say": "<p>BCD nén cất hai chữ số thập phân trong một byte, mỗi chữ số 4 bit. 47H ở dạng BCD là số 47, còn ở nhị phân thường là 71.<\/p>"}, {"t": "SWAP A → 74H: đổi hai nibble", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Sau SWAP A<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">SWAP A → 0C4H · 1 byte, 1 chu kỳ máy<\/p>"}, {"t": "ANL A,#0FH → 04H; ORL A,#30H → 34H = '4'", "html": "<p class=\"mt-calc\">ANL A,#0FH → 54H 0FH · 2 byte, 1 chu kỳ máy · A = 04H<\/p><p class=\"mt-calc\">ORL A,#30H → 44H 30H · 2 byte, 1 chu kỳ máy · A = 34H<\/p>", "ask": {"q": "A = 34H gửi ra màn hình ASCII in ra gì?", "o": ["Số 34", "Ký tự ‘4’", "Ký tự ‘D’"], "a": 1}}, {"t": "Hàng đơn vị: ANL A,#0FH → 07H; ADD A,#30H → 37H = '7'", "html": "<p class=\"mt-calc\">MOV A,#47H → ANL A,#0FH → 07H → ADD A,#30H → 37H = ‘7’<\/p>", "say": "<p>Với 00H…09H, <code>ORL A,#30H<\/code> và <code>ADD A,#30H<\/code> cho cùng kết quả vì nibble cao đang bằng 0.<\/p>"}, {"t": "Cách khác: MOV B,#10H, DIV AB → A = 04H, B = 07H", "html": "<p class=\"mt-calc\">MOV B,#10H → 75H 0F0H 10H · 3 byte, 2 chu kỳ máy<\/p><p class=\"mt-calc\">DIV AB → 84H · 1 byte, 4 chu kỳ máy<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Cách lấy nibble cao<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>SWAP A / ANL A,#0FH<\/td><td class=\"ok\">3<\/td><td class=\"ok\">2<\/td><\/tr><tr><td>MOV B,#10H / DIV AB<\/td><td>4<\/td><td>6<\/td><\/tr><\/tbody><\/table>", "say": "<p>Chia cho 16 cho cả thương (hàng chục) lẫn số dư (hàng đơn vị), nhưng <code>DIV AB<\/code> mất 4 chu kỳ máy. Kết quả A = 04H, B = 07H đã chạy trên s51.<\/p>"}]}, {"label": "Ví dụ: Cộng BCD bằng ADD rồi DA A", "note": "38 + 29 = 67; 75 + 48 = 123 (CY là hàng trăm).", "steps": [{"t": "Hai số BCD nén: 38H (38) và 29H (29)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">Đọc như BCD<\/th><th scope=\"col\">Đọc như nhị phân<\/th><\/tr><\/thead><tbody><tr><td>38H<\/td><td>38<\/td><td>56<\/td><\/tr><tr><td>29H<\/td><td>29<\/td><td>41<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mục tiêu: A = 38 + 29 = 67 ở dạng BCD nén, tức 67H, để đưa thẳng ra hai chữ số hiển thị.<\/p>"}, {"t": "38H + 29H: ADD cho 61H, AC = 1", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A = 38H<\/td><td><\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>+ 29H<\/td><td><\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau ADD<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">CY = 0 · AC = 1 (8 + 9 = 17: nhớ từ bit 3 sang bit 4)<\/p>", "ask": {"q": "61H có phải là 38 + 29 viết ở dạng BCD không?", "o": ["Có: 61H là đúng", "Không: 38 + 29 = 67"], "a": 1}, "say": "<p>Mạch cộng làm việc ở hệ 2: nibble thấp 8 + 9 = 17 = 11H, để lại 1 và nhớ 16 sang nibble cao. Trong hệ 10 phải nhớ 10, nên kết quả thiếu 6.<\/p>"}, {"t": "DA A → 67H = 38 + 29", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau DA A<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">DA A → 0D4H · 1 byte, 1 chu kỳ máy · cộng 06H vì AC = 1<\/p>", "say": "<p><code>DA A<\/code> (chỉnh thập phân): nibble thấp lớn hơn 9 hoặc AC = 1 thì cộng 06H; sau đó nibble cao lớn hơn 9 hoặc CY = 1 thì cộng 60H.<\/p>"}, {"t": "75H + 48H: ADD cho 0BDH, hai nibble đều lớn hơn 9", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A = 75H<\/td><td><\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>+ 48H<\/td><td><\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Sau ADD<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">CY = 0 · AC = 0<\/p>"}, {"t": "DA A → 23H, CY = 1: 75 + 48 = 123", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau DA A<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">0BDH + 06H = 0C3H; nibble cao 0CH > 9 nên + 60H = 123H: byte giữ 23H, CY = 1<\/p>", "ask": {"q": "Sau DA A, CY = 1. Điều đó nghĩa là gì?", "o": ["Có chữ số hàng trăm: 123", "Phép cộng bị lỗi, bỏ kết quả", "Kết quả âm"], "a": 0}, "say": "<p>Cả bốn trạng thái (61H, 67H, 0BDH, 23H với CY) đã chạy trên s51. 8086 có lệnh tương ứng <code>DAA<\/code> (mã 27H) cho AL.<\/p>"}]}, {"label": "Lỗi: Nhầm số 5 với ký tự ‘5’", "note": "Hiển thị cần mã ASCII; tính toán cần giá trị.", "steps": [{"t": "A = 05H (giá trị 5) gửi thẳng ra màn hình", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">Đọc như số<\/th><th scope=\"col\">Đọc như ASCII<\/th><\/tr><\/thead><tbody><tr><td>05H<\/td><td>5<\/td><td class=\"bad\">mã điều khiển<\/td><\/tr><tr><td>35H<\/td><td>53<\/td><td class=\"ok\">ký tự ‘5’<\/td><\/tr><\/tbody><\/table>", "say": "<p>Giả định: thiết bị hiển thị (LCD ký tự, cửa sổ terminal) nhận mã ASCII. Byte 05H là mã điều khiển nên không có chữ nào hiện ra. Đây là lỗi “nhầm 5 với ký tự ‘5’” của lab gốc.<\/p>"}, {"t": "Sửa: ORL A,#30H → 35H = ‘5’", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Mặt nạ<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Sau ORL<\/td><td>0<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">ORL A,#30H → 44H 30H · 2 byte, 1 chu kỳ máy<\/p>", "ask": {"q": "Sau ORL A,#30H, màn hình in ra gì?", "o": ["Số 35", "Ký tự ‘5’", "Ký tự ‘E’"], "a": 1}}, {"t": "Chiều ngược: phím ‘5’ + phím ‘5’ cộng thẳng", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>‘5’ = 35H<\/td><td><\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>+ ‘5’ = 35H<\/td><td><\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau ADD<\/td><td>0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">35H + 35H = 6AH = ký tự ‘j’, không phải 10<\/p>", "ask": {"q": "Bàn phím gửi mã ASCII. Cộng thẳng hai phím ‘5’ được gì?", "o": ["0AH = 10", "70 (thập phân)", "6AH: ký tự ‘j’, không phải 10"], "a": 2}}, {"t": "Sửa: ANL A,#0FH đổi ký tự thành giá trị", "html": "<p class=\"mt-calc\">‘5’ = 35H → ANL A,#0FH → 05H; 05H + 05H = 0AH = 10 ✓<\/p>", "say": "<p>Quy tắc: giá trị → ký tự thì cộng (hoặc OR) 30H; ký tự → giá trị thì trừ 30H (hoặc AND 0FH, chỉ khi chắc chắn là chữ số ‘0’…‘9’). Kết quả cả hai đường đã chạy trên s51.<\/p>"}]}, {"label": "Bẫy: Quên CLR C trước RLC", "note": "CY cũ đi vào bit 0, kết quả lệch 1.", "steps": [{"t": "CY = 1 sót lại từ phép tính trước", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">MOV A,#15H không đổi CY<\/p>", "say": "<p>Giả lập bằng <code>SETB C<\/code>: một phép cộng hay so sánh trước đó để lại CY = 1. Lệnh MOV vào A không chạm CY.<\/p>"}, {"t": "RLC A → 2BH = 43, không phải 42", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau RLC A<\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div>", "ask": {"q": "CY = 1 trước RLC A, A = 15H. A sau lệnh bằng bao nhiêu?", "o": ["2BH = 43", "2AH = 42", "0AH = 10"], "a": 0}, "say": "<p>RLC đưa CY cũ vào bit 0: kết quả lệch 1. Không có lỗi biên dịch, chỉ sai số liệu.<\/p>"}, {"t": "Sửa: CLR C ngay trước mỗi RLC / RRC dùng để dịch", "html": "<p class=\"mt-calc\">CLR C → 0C3H · 1 byte, 1 chu kỳ máy · thêm 1 byte, 1 chu kỳ máy<\/p><p class=\"mt-calc\">Khi biết chắc bit 7 = 0: RL A cũng cho A × 2 và không cần CY<\/p>", "say": "<p>Đây là cùng kiểu lỗi “quên CLR C trước SUBB” của Bài 2: lệnh 8051 đọc CY như một đầu vào.<\/p>"}]}, {"label": "Bẫy: SHR với số có dấu (8086)", "note": "SHR làm −8 thành 124; SAR giữ dấu.", "steps": [{"t": "8086: AL = 0F8H, hiểu là số có dấu −8", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>AL<\/td><td class=\"new\">1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">MOV AL,0F8h → 0B0H 0F8H · 248 không dấu = −8 có dấu<\/p>"}, {"t": "SHR AL,1 → 7CH = 124: mất dấu", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td><\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Sau SHR<\/td><td>0<\/td><td class=\"new\">0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">SHR AL,1 → 0D0H 0E8H · CF = 0 · SF = 0<\/p>", "ask": {"q": "AL là số có dấu −8. SHR AL,1 cho AL hiểu là số có dấu bằng bao nhiêu?", "o": ["−4", "124: sai, mất dấu", "−16"], "a": 1}, "say": "<p>SHR đưa 0 vào bit 7: đúng cho số không dấu (248 ÷ 2 = 124) nhưng làm số âm thành số dương.<\/p>"}, {"t": "SAR AL,1 → 0FCH = −4: giữ bit dấu", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td><\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Sau SAR<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">SAR AL,1 → 0D0H 0F8H<\/p>", "say": "<p>Dịch phải số học chép bit 7 cũ vào bit 7 mới. Đã kiểm SHR, SAR với mọi giá trị AL trên CPU x86 thật. Lưu ý: −7 (0F9H) SAR 1 cho −4, tức làm tròn xuống, không phải −3.<\/p>"}, {"t": "8051 không có SAR: MOV C,ACC.7 rồi RRC A", "html": "<p class=\"mt-calc\">MOV C,ACC.7 → 0A2H 0E7H · 2 byte, 1 chu kỳ máy · chép bit dấu vào CY<\/p><p class=\"mt-calc\">RRC A → 13H · 1 byte, 1 chu kỳ máy · 0F8H → 0FCH (s51)<\/p>", "say": "<p>Trên 8086, số đếm của lệnh dịch là 1 hoặc thanh ghi CL: <code>MOV CL,4<\/code> / <code>SHR AL,CL<\/code>. Dạng <code>SHR AL,4<\/code> chỉ có từ 80186; NASM ở chế độ 8086 báo lỗi “no instruction for this cpu level”.<\/p>"}]}, {"label": "Bẫy: DA A sau SUBB", "note": "DA A chỉ chỉnh phép cộng; dùng bù 100.", "steps": [{"t": "42H − 15H bằng SUBB → 2DH, AC = 1", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A = 42H<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>− 15H<\/td><td><\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau SUBB<\/td><td>0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">SUBB A,#15H → 94H 15H · 2 byte, 1 chu kỳ máy · CY = 0 · AC = 1<\/p>"}, {"t": "DA A → 33H: sai (42 − 15 = 27)", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau DA A<\/td><td>0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div>", "ask": {"q": "DA A cho 33H. Đây có phải 42 − 15 ở dạng BCD?", "o": ["Có: 42 − 15 = 33", "Không: DA A chỉ dùng sau phép cộng, đúng là 27"], "a": 1}, "say": "<p>DA A của 8051 luôn chỉnh theo kiểu phép cộng (cộng 06H, 60H). Sau phép trừ cần trừ 06H, nên kết quả sai mà không có cờ báo.<\/p>"}, {"t": "Sửa: cộng bù 100: 42H + 85H → 0C7H", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>A = 42H<\/td><td><\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>+ 85H<\/td><td><\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Sau ADD<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">bù 100 của 15 là 100 − 15 = 85 → ADD A,#85H → 24H 85H · 2 byte, 1 chu kỳ máy<\/p>"}, {"t": "DA A → 27H, CY = 1: kết quả không âm", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">CY<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trước<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Sau DA A<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div>", "ask": {"q": "42 + 85 = 127. Vì sao đáp án là 27?", "o": ["Bỏ chữ số hàng trăm (CY = 1); 42 − 15 = 42 + 85 − 100", "DA A tự trừ 100", "Do AC = 1"], "a": 0}, "say": "<p>Cả hai đường đã chạy trên s51. 8086 có lệnh <code>DAS<\/code> (mã 2FH) để chỉnh sau phép trừ; 8051 thì không.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l4"),"l4",[{"kind": "base", "t": "Dịch bit, BCD và mã ASCII", "d": "<p>Tính từng câu và trả lời ở hệ 16 (viết 5A, 5AH hoặc 0x5A đều được). Phép dịch làm trên byte 8 bit, bit rơi ra ngoài bị bỏ; bit đưa vào là 0.<\/p>", "items": [{"q": "35H dịch trái 1 bit (CLR C rồi RLC A)", "f": "hex", "a": 106}, {"q": "0B4H dịch phải logic 1 bit (CLR C rồi RRC A)", "f": "hex", "a": 90}, {"q": "SWAP A với A = 0A7H", "f": "hex", "a": 122}, {"q": "Mã ASCII của ký tự '9'", "f": "hex", "a": 57}, {"q": "Mã ASCII của chữ hoa 'D'", "f": "hex", "a": 68}, {"q": "Số thập phân 86 ở dạng BCD nén (1 byte)", "f": "hex", "a": 134}, {"q": "Số thập phân 86 ở dạng nhị phân thường (1 byte)", "f": "hex", "a": 86}, {"q": "A = 38H, chạy ADD A,#29H rồi DA A: A bằng", "f": "hex", "a": 103}], "hints": ["Dịch trái 1 bit = nhân 2 (bỏ bit 7); dịch phải logic 1 bit = chia 2 lấy phần nguyên. SWAP đổi chỗ hai nibble: 0A7H → 7AH.", "Chữ số '0'…'9' có mã 30H…39H; chữ hoa 'A'…'Z' có mã 41H…5AH (A = 41H, B = 42H…).", "BCD nén: mỗi chữ số thập phân chiếm một nibble, nên 86 → 86H. Nhị phân thường: 86 = 5 × 16 + 6. DA A sau ADD: nibble thấp lớn hơn 9 hoặc AC = 1 thì cộng 06H."], "why": "35H = 0011 0101B → 0110 1010B = 6AH (53 × 2 = 106); 0B4H = 180 → 90 = 5AH; SWAP 0A7H = 7AH; '9' = 39H; 'D' = 41H + 3 = 44H; 86 BCD nén = 86H; 86 = 56H; 38H + 29H = 61H với AC = 1, DA A cộng 06H → 67H (38 + 29 = 67)."}, {"kind": "pick", "t": "Thiết bị hiển thị sẽ in ra gì?", "d": "<p>A chứa <b>giá trị<\/b> một chữ số 0…9 (00H…09H). Lệnh tiếp theo gửi A ra một thiết bị hiển thị nhận mã ASCII (LCD ký tự hoặc cửa sổ terminal; giả định của bài). Mỗi dòng dưới đây là lệnh đặt ngay trước lệnh gửi. Xếp mỗi dòng vào nhóm đúng, xét với <b>mọi<\/b> chữ số 0…9.<\/p>", "cats": ["In đúng chữ số '0'…'9'", "Gửi mã điều khiển: không in ra chữ", "In ký tự khác chữ số"], "items": [{"q": "ORL A,#30H", "a": 0}, {"q": "ADD A,#30H", "a": 0}, {"q": "XRL A,#30H", "a": 0}, {"q": "Không thêm lệnh (gửi thẳng A)", "a": 1}, {"q": "ANL A,#0FH", "a": 1}, {"q": "ANL A,#30H", "a": 1}, {"q": "ADD A,#41H", "a": 2}, {"q": "ORL A,#20H", "a": 2}], "hints": ["Mã ASCII 00H…1FH là mã điều khiển (không phải chữ in được); chữ số '0'…'9' là 30H…39H.", "Với A = 00H…09H, nibble cao bằng 0 nên OR 30H, cộng 30H và XOR 30H cho cùng kết quả 30H…39H.", "41H là 'A': cộng 41H cho 'A'…'J'. 20H là dấu cách: OR 20H cho các mã 20H…29H (dấu cách, !, \", #…)."], "why": "ORL, ADD, XRL với 30H đều cho 30H…39H = '0'…'9'. Gửi thẳng 00H…09H hoặc sau ANL A,#0FH (giữ nguyên) là mã điều khiển; ANL A,#30H cho 00H. ADD A,#41H cho 41H…4AH = 'A'…'J'; ORL A,#20H cho 20H…29H (dấu cách và dấu câu). Đây đúng là lỗi nhầm số 5 với ký tự '5' của Ví dụ 6."}, {"kind": "num", "t": "Nhân 4 và tách nibble: tối ưu byte, chu kỳ máy", "d": "<p>8051 kiểu gốc, thạch anh 12 MHz (1 chu kỳ máy = 1 µs). A chứa số không dấu không quá 3FH (63), nên A × 4 vừa 8 bit. Hai cách nhân A với 4: (a) <code>RL A<\/code> / <code>RL A<\/code>; (b) <code>MOV B,#04H<\/code> / <code>MUL AB<\/code>. Cách (c) lấy nibble cao của A: <code>SWAP A<\/code> / <code>ANL A,#0FH<\/code>. Trả lời số byte mã máy và số chu kỳ máy.<\/p>", "items": [{"q": "(a) RL A, RL A: tổng số byte", "a": 2}, {"q": "(a) RL A, RL A: tổng số chu kỳ máy", "a": 2}, {"q": "(b) MOV B,#04H, MUL AB: tổng số byte", "a": 4}, {"q": "(b) MOV B,#04H, MUL AB: tổng số chu kỳ máy", "a": 6}, {"q": "Đoạn chạy 1 000 lần trong vòng lặp: thay (b) bằng (a) tiết kiệm bao nhiêu µs", "a": 4000, "unit": "µs"}, {"q": "(c) SWAP A, ANL A,#0FH: tổng số byte", "a": 3}, {"q": "(c) SWAP A, ANL A,#0FH: tổng số chu kỳ máy", "a": 2}], "hints": ["RL A, SWAP A: 1 byte, 1 chu kỳ máy. ANL A,#data: 2 byte, 1 chu kỳ máy. MOV B,#data: 3 byte (opcode, địa chỉ B, hằng), 2 chu kỳ máy.", "MUL AB và DIV AB: 1 byte nhưng 4 chu kỳ máy, lâu nhất trong tập lệnh 8051.", "Mỗi lần chạy tiết kiệm 6 − 2 = 4 chu kỳ máy = 4 µs; nhân với số lần lặp."], "why": "RL A = 23H (1 byte, 1 CKM) nên (a) 2 byte, 2 CKM; vì bit 7, bit 6 của A bằng 0 nên quay trái 2 lần đúng bằng nhân 4. MOV B,#04H = 75H 0F0H 04H (3 byte, 2 CKM) và MUL AB = A4H (1 byte, 4 CKM) nên (b) 4 byte, 6 CKM. 1 000 × (6 − 2) µs = 4 000 µs. SWAP A = C4H, ANL A,#0FH = 54H 0FH: (c) 3 byte, 2 CKM, nhanh hơn MOV B,#10H / DIV AB (4 byte, 6 CKM)."}]);

makeQuiz("quiz4","score4",[{"q": "Ký tự '7' (phím số bảy) có mã ASCII là bao nhiêu?", "o": ["07H", "77H", "70H", "37H"], "a": 3, "e": "Chữ số '0'…'9' có mã 30H…39H, nên '7' = 37H. 07H là giá trị số 7 (trong ASCII là mã điều khiển, không in ra chữ); 77H là chữ thường 'w'; 70H là chữ 'p'."}, {"q": "8051: A = 97H. Chạy CLR C rồi RRC A. Kết quả là gì?", "o": ["A = 0CBH, CY = 1", "A = 4BH, CY = 1", "A = 4BH, CY = 0", "A = 2EH, CY = 1"], "a": 1, "e": "97H = 1001 0111B. RRC đưa CY (= 0) vào bit 7 và bit 0 (= 1) ra CY: 0100 1011B = 4BH, CY = 1 (151 = 2 × 75 + 1). 0CBH là kết quả của RR A (bit 0 quay về bit 7); 2EH là của RLC A."}, {"q": "Số thập phân 59 viết ở dạng BCD nén trong một byte là gì?", "o": ["3BH", "95H", "59H", "35H 39H"], "a": 2, "e": "BCD nén đặt mỗi chữ số thập phân vào một nibble: 5 ở nibble cao, 9 ở nibble thấp → 59H. 3BH là 59 ở nhị phân thường; 95H đảo ngược hai nibble; 35H 39H là hai ký tự ASCII '5', '9' (hai byte)."}, {"q": "8051: MOV A,#38H / ADD A,#29H / DA A. Chạy xong, A bằng bao nhiêu?", "o": ["67H", "61H", "43H", "0C7H"], "a": 0, "e": "ADD cho 61H với AC = 1 (8 + 9 có nhớ từ bit 3), DA A cộng 06H → 67H, tức 38 + 29 = 67 dạng BCD. 61H là kết quả trước DA A; 43H là 67 viết ở nhị phân thường; 0C7H là cộng nhầm 66H."}, {"q": "8086: AL = 0F0h, hiểu là số có dấu −16. Lệnh nào cho AL = −8?", "o": ["SHR AL,1", "ROR AL,1", "SAR AL,1", "SHL AL,1"], "a": 2, "e": "SAR giữ bit dấu: 1111 0000B → 1111 1000B = 0F8h = −8. SHR đưa 0 vào bit 7: 78h = 120; ROR AL,1 cũng cho 78h (bit 0 = 0 quay lên bit 7); SHL nhân 2: 0E0h = −32."}]);

